void ui_DocWinTabView_event_handler(lv_event_t *e)
{
    lv_event_code_t code = lv_event_get_code(e);
    if (code == LV_EVENT_VALUE_CHANGED)
    {
        int cengID = lv_tabview_get_tab_act(ui_DocWinTabView);

        lv_obj_add_flag(ui_JXYLceng1, LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(ui_JXYLceng2, LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(ui_JXYLceng3, LV_OBJ_FLAG_HIDDEN);

        switch (cengID)
        {
        case 0: // 三层
            lv_obj_clear_flag(ui_JXYLceng3, LV_OBJ_FLAG_HIDDEN);
            break;
        case 1: // 二层
            lv_obj_clear_flag(ui_JXYLceng2, LV_OBJ_FLAG_HIDDEN);
            break;
        case 2: // 一层
            lv_obj_clear_flag(ui_JXYLceng1, LV_OBJ_FLAG_HIDDEN);
            break;
        default:
            lv_obj_clear_flag(ui_JXYLceng1, LV_OBJ_FLAG_HIDDEN);
            break;
        }

        DBG_MSG("切换到楼层索引: %d", (int)cengID);
    }
}
